"""Keep the measured reference; R22 contact strength is authored in C++."""
import hashlib
import json
from pathlib import Path

output = Path(__file__).parent
project = output.parents[1]
source = output.parent / 'Super90LoaderR16_20261009/camera_curves.json'
curves = json.loads(source.read_text(encoding='utf-8'))['curves']
header = [
    '#pragma once', '#include "CoreMinimal.h"', '',
    '// Generated by Super90LoaderR22_20261010/prepare_camera.py.',
    '// R16 measured background only; contact impulses are applied once in C++.',
    '// Source timing is unchanged; X/Y are image displacement / frame width, Z is image roll.',
    'namespace Super90LoaderCameraReference', '{',
]
for name, rows in curves.items():
    header.append(f'inline const FVector3f {name.capitalize()}[] = {{')
    header.extend('    {' + ', '.join(f'{v:.9f}f' for v in row) + '},' for row in rows)
    header.append('};')
header.append('}')
target = project / 'Source/FPSGAME/Weapons/Super90LoaderCameraReference.h'
target.write_text('\n'.join(header) + '\n', encoding='utf-8')
(output / 'camera_source.json').write_text(json.dumps({
    'file': str(target),
    'sha256': hashlib.sha256(target.read_bytes()).hexdigest(),
    'reference': str(source),
    'contact_response': 'WeaponActionCameraComponent.cpp; ASH-12 / PKM strength, shared ImpactScale',
    'response_lag_source_frames': 1.4,
    'runtime_tested': False,
}, indent=2), encoding='utf-8')
print('R22_CAMERA_SOURCE_SAVED', flush=True)
